165	std::string getFieldString(const uri_split_result& res, int field,
166	                           const char* base)
167	{
168	  if (res.field_set & (1 << field)) {
169	    return std::string(base + res.fields[field].off, res.fields[field].len);
170	  }
171	  return "";
172	}
