197	  if (us.port != 0 && defPort != us.port) {
198	    res += fmt(":%u", us.port);
199	  }
200	
201	  res += us.dir;
202	  if (us.dir.empty() || us.dir[us.dir.size() - 1] != '/') {
203	    res += "/";
204	  }
205	
206	  res += us.file;
207	  res += us.query;
