211	namespace {
212	enum { NPATH_START, NPATH_SLASH, NPATH_SDOT, NPATH_DDOT, NPATH_PATHCOMP };
213	}
214	
215	std::string normalizePath(std::string path)
216	{
217	  auto begin = path.begin(), out = begin;
218	  int state = NPATH_START;
219	  bool startWithSlash = false;
220	  std::vector<int> range;
221	  // 32 is arbitrary
222	  range.reserve(32);
223	
224	  for (auto in = begin, eoi = path.end(); in != eoi; ++in) {
225	    switch (state) {
226	    case NPATH_START:
227	      switch (*in) {
228	      case '.':
229	        state = NPATH_SDOT;
230	        range.push_back(in - begin);
231	        break;
232	      case '/':
233	        startWithSlash = true;
234	        state = NPATH_SLASH;
235	        break;
236	      default:
237	        state = NPATH_PATHCOMP;
238	        range.push_back(in - begin);
239	        break;
240	      }
241	      break;
242	    case NPATH_SLASH:
243	      switch (*in) {
244	      case '.':
245	        state = NPATH_SDOT;
246	        range.push_back(in - begin);
247	        break;
248	      case '/':
249	        // drop duplicate '/'
250	        break;
251	      default:
252	        state = NPATH_PATHCOMP;
253	        range.push_back(in - begin);
254	        break;
255	      }
256	      break;
257	    case NPATH_SDOT:
258	      switch (*in) {
259	      case '.':
260	        state = NPATH_DDOT;
261	        break;
262	      case '/':
263	        // drop path component '.'
264	        state = NPATH_SLASH;
265	        range.pop_back();
266	        break;
267	      default:
268	        state = NPATH_PATHCOMP;
269	        break;
270	      }
271	      break;
272	    case NPATH_DDOT:
273	      switch (*in) {
274	      case '/':
275	        // drop previous path component before '..'
276	        for (int i = 0; i < 3 && !range.empty(); ++i) {
277	          range.pop_back();
278	        }
279	        state = NPATH_SLASH;
280	        break;
281	      default:
282	        state = NPATH_PATHCOMP;
283	        break;
284	      }
285	      break;
286	    case NPATH_PATHCOMP:
287	      if (*in == '/') {
288	        range.push_back(in + 1 - begin);
289	        state = NPATH_SLASH;
290	      }
291	      break;
292	    }
293	  }
294	
295	  switch (state) {
296	  case NPATH_SDOT:
297	    range.pop_back();
298	    break;
299	  case NPATH_DDOT:
300	    for (int i = 0; i < 3 && !range.empty(); ++i) {
301	      range.pop_back();
302	    }
303	    break;
304	  case NPATH_PATHCOMP:
305	    range.push_back(path.end() - begin);
306	    break;
307	  default:
308	    break;
309	  }
310	
311	  if (startWithSlash) {
312	    ++out;
313	  }
314	
315	  for (int i = 0; i < (int)range.size(); i += 2) {
316	    auto a = begin + range[i];
317	    auto b = begin + range[i + 1];
318	    if (a == out) {
319	      out = b;
320	    }
321	    else {
322	      out = std::copy(a, b, out);
323	    }
324	  }
325	
326	  path.erase(out, path.end());
327	  return path;
328	}
329	
330	namespace {
331	std::string joinPath(std::string basePath,
332	                     std::string::const_iterator newPathFirst,
333	                     std::string::const_iterator newPathLast)
334	{
335	  if (newPathFirst == newPathLast) {
336	    return basePath;
337	  }
338	
339	  if (basePath.empty() || *newPathFirst == '/') {
340	    return normalizePath(std::string(newPathFirst, newPathLast));
341	  }
342	
343	  if (basePath[basePath.size() - 1] == '/') {
344	    basePath.append(newPathFirst, newPathLast);
345	    return normalizePath(basePath);
346	  }
347	
348	  basePath += "/";
349	  basePath.append(newPathFirst, newPathLast);
350	  return normalizePath(basePath);
351	}
352	} // namespace
353	
354	std::string joinPath(const std::string& basePath, const std::string& newPath)
355	{
356	  return joinPath(basePath, newPath.begin(), newPath.end());
357	}
358	
359	std::string joinUri(const std::string& baseUri, const std::string& uri)
360	{
361	  UriStruct us;
362	  if (parse(us, uri)) {
363	    return uri;
364	  }
365	
366	  UriStruct bus;
367	  if (!parse(bus, baseUri)) {
368	    return uri;
369	  }
370	
371	  std::string::const_iterator qend;
372	  for (qend = uri.begin(); qend != uri.end(); ++qend) {
373	    if (*qend == '#') {
374	      break;
375	    }
376	  }
377	  std::string::const_iterator end;
378	  for (end = uri.begin(); end != qend; ++end) {
379	    if (*end == '?') {
380	      break;
381	    }
382	  }
383	  std::string newpath = joinPath(bus.dir, uri.begin(), end);
384	  bus.dir.clear();
385	  bus.file.clear();
386	  bus.query.clear();
387	  std::string res = construct(bus);
388	  if (!newpath.empty()) {
389	    // res always ends with '/'. Since bus.dir also starts with '/',
390	    // regardless of uri, newpath always starts with '/'.
391	    res.append(newpath.begin() + 1, newpath.end());
392	  }
393	  res.append(end, qend);
394	  return res;
395	}
396	
397	} // namespace uri
398	
399	} // namespace aria2
