88	bool parse(UriStruct& result, const std::string& uri)
89	{
90	  uri_split_result res;
91	  int rv;
92	  const char* p = uri.c_str();
93	  rv = uri_split(&res, p);
94	  if (rv != 0) {
95	    return false;
96	  }
97	
98	  result.protocol.assign(p + res.fields[USR_SCHEME].off,
99	                         res.fields[USR_SCHEME].len);
100	  result.host.assign(p + res.fields[USR_HOST].off, res.fields[USR_HOST].len);
101	  if (res.port == 0) {
102	    uint16_t defPort;
103	    if ((defPort = getDefaultPort(result.protocol)) == 0) {
104	      return false;
105	    }
106	    result.port = defPort;
107	  }
108	  else {
109	    result.port = res.port;
110	  }
111	
112	  if (res.field_set & (1 << USR_PATH)) {
113	    if (res.field_set & (1 << USR_BASENAME)) {
114	      result.dir.assign(p + res.fields[USR_PATH].off,
115	                        res.fields[USR_PATH].len -
116	                            res.fields[USR_BASENAME].len);
117	      result.file.assign(p + res.fields[USR_BASENAME].off,
118	                         res.fields[USR_BASENAME].len);
119	    }
120	    else {
121	      result.dir.assign(p + res.fields[USR_PATH].off, res.fields[USR_PATH].len);
122	      result.file = A2STR::NIL;
123	    }
124	  }
125	  else {
126	    result.dir = "/";
127	    result.file = A2STR::NIL;
128	  }
129	
130	  if (res.field_set & (1 << USR_QUERY)) {
131	    result.query = "?";
132	    result.query.append(p + res.fields[USR_QUERY].off,
133	                        res.fields[USR_QUERY].len);
134	  }
135	  else {
136	    result.query = A2STR::NIL;
137	  }
138	
139	  if (res.field_set & (1 << USR_USER)) {
140	    result.username.assign(p + res.fields[USR_USER].off,
141	                           res.fields[USR_USER].len);
142	    result.username =
143	        util::percentDecode(result.username.begin(), result.username.end());
144	  }
145	  else {
146	    result.username = A2STR::NIL;
147	  }
148	
149	  if (res.field_set & (1 << USR_PASSWD)) {
150	    result.hasPassword = true;
151	    result.password.assign(p + res.fields[USR_PASSWD].off,
152	                           res.fields[USR_PASSWD].len);
153	    result.password =
154	        util::percentDecode(result.password.begin(), result.password.end());
155	  }
156	  else {
157	    result.hasPassword = false;
158	    result.password = A2STR::NIL;
159	  }
160	
161	  result.ipv6LiteralAddress = res.flags & USF_IPV6ADDR;
162	  return true;
163	}
