174	std::string construct(const UriStruct& us)
175	{
176	  std::string res;
177	  res += us.protocol;
178	  res += "://";
179	  if (!us.username.empty()) {
180	    res += util::percentEncode(us.username);
181	    if (us.hasPassword) {
182	      res += ":";
183	      res += util::percentEncode(us.password);
184	    }
185	    res += "@";
186	  }
187	  if (us.ipv6LiteralAddress) {
188	    res += "[";
189	    res += us.host;
190	    res += "]";
191	  }
192	  else {
193	    res += us.host;
194	  }
195	
196	  uint16_t defPort = getDefaultPort(us.protocol);
197	  if (us.port != 0 && defPort != us.port) {
198	    res += fmt(":%u", us.port);
199	  }
200	
201	  res += us.dir;
202	  if (us.dir.empty() || us.dir[us.dir.size() - 1] != '/') {
203	    res += "/";
204	  }
205	
206	  res += us.file;
207	  res += us.query;
208	  return res;
