116	template <typename InputIterator>
117	std::pair<InputIterator, InputIterator>
118	stripIter(InputIterator first, InputIterator last,
119	          const char* chars = DEFAULT_STRIP_CHARSET)
120	{
121	  for (; first != last && strchr(chars, *first) != 0; ++first)
122	    ;
123	  if (first == last) {
124	    return std::make_pair(first, last);
125	  }
126	  InputIterator left = last - 1;
127	  for (; left != first && strchr(chars, *left) != 0; --left)
128	    ;
129	  return std::make_pair(first, left + 1);
130	}
