177	template <typename T> std::string uitos(T n, bool comma = false)
178	{
179	  std::string res;
180	  if (n == 0) {
181	    res = "0";
182	    return res;
183	  }
184	  int i = 0;
185	  T t = n;
186	  for (; t; t /= 10, ++i)
187	    ;
188	  if (comma) {
189	    i += (i - 1) / 3;
190	  }
191	  res.resize(i);
192	  --i;
193	  for (int j = 0; n; --i, ++j, n /= 10) {
194	    res[i] = (n % 10) + '0';
195	    if (comma && i > 1 && (j + 1) % 3 == 0) {
196	      res[--i] = ',';
197	    }
198	  }
199	  return res;
200	}
