251	// Converts hexadecimal ascii characters in [first, last) into packed
252	// binary form and return the result. If characters in given range is
253	// not well formed, then empty string is returned.
254	template <typename InputIterator>
255	std::string fromHex(InputIterator first, InputIterator last)
256	{
257	  std::string dest;
258	  size_t len = last - first;
259	  if (len % 2) {
260	    return dest;
261	  }
262	  for (; first != last; first += 2) {
263	    unsigned char high = hexCharToUInt(*first);
264	    unsigned char low = hexCharToUInt(*(first + 1));
265	    if (high == 255 || low == 255) {
266	      dest.clear();
267	      return dest;
268	    }
269	    dest += (high * 16 + low);
270	  }
271	  return dest;
272	}
