488	/**
489	 * Take a string [first, last) which is a delimited list and add its
490	 * elements into result as iterator pair. result is stored in out.
491	 */
492	template <typename InputIterator, typename OutputIterator>
493	OutputIterator splitIter(InputIterator first, InputIterator last,
494	                         OutputIterator out, char delim, bool doStrip = false,
495	                         bool allowEmpty = false)
496	{
497	  for (InputIterator i = first; i != last;) {
498	    InputIterator j = std::find(i, last, delim);
499	    std::pair<InputIterator, InputIterator> p(i, j);
500	    if (doStrip) {
501	      p = stripIter(i, j);
502	    }
503	    if (allowEmpty || p.first != p.second) {
504	      *out++ = p;
505	    }
506	    i = j;
507	    if (j != last) {
508	      ++i;
509	    }
510	  }
511	  if (allowEmpty && (first == last || *(last - 1) == delim)) {
512	    *out++ = std::make_pair(last, last);
513	  }
514	  return out;
515	}
