517	template <typename InputIterator, typename OutputIterator>
518	OutputIterator splitIterM(InputIterator first, InputIterator last,
519	                          OutputIterator out, const char* delims,
520	                          bool doStrip = false, bool allowEmpty = false)
521	{
522	  size_t numDelims = strlen(delims);
523	  const char* dlast = delims + numDelims;
524	  for (InputIterator i = first; i != last;) {
525	    InputIterator j = i;
526	    for (; j != last && std::find(delims, dlast, *j) == dlast; ++j)
527	      ;
528	    std::pair<InputIterator, InputIterator> p(i, j);
529	    if (doStrip) {
530	      p = stripIter(i, j);
531	    }
532	    if (allowEmpty || p.first != p.second) {
533	      *out++ = p;
534	    }
535	    i = j;
536	    if (j != last) {
537	      ++i;
538	    }
539	  }
540	  if (allowEmpty &&
541	      (first == last || std::find(delims, dlast, *(last - 1)) != dlast)) {
542	    *out++ = std::make_pair(last, last);
543	  }
544	  return out;
