547	template <typename InputIterator, typename OutputIterator>
548	OutputIterator split(InputIterator first, InputIterator last,
549	                     OutputIterator out, char delim, bool doStrip = false,
550	                     bool allowEmpty = false)
551	{
552	  for (InputIterator i = first; i != last;) {
553	    InputIterator j = std::find(i, last, delim);
554	    std::pair<InputIterator, InputIterator> p(i, j);
555	    if (doStrip) {
556	      p = stripIter(i, j);
557	    }
558	    if (allowEmpty || p.first != p.second) {
559	      *out++ = std::string(p.first, p.second);
560	    }
561	    i = j;
562	    if (j != last) {
563	      ++i;
564	    }
