593	struct CaseCmp {
594	  bool operator()(char lhs, char rhs) const
595	  {
596	    if ('A' <= lhs && lhs <= 'Z') {
597	      lhs += 'a' - 'A';
598	    }
599	    if ('A' <= rhs && rhs <= 'Z') {
600	      rhs += 'a' - 'A';
601	    }
602	    return lhs == rhs;
603	  }
604	};
