789	// Parses sequence [first, last) and find name=value pair delimited by
790	// delim character. If name(and optionally value) is found, returns
791	// pair of iterator which can use as first parameter of next call of
792	// this function, and true. If no name is found, returns the pair of
793	// last and false.
794	template <typename Iterator>
795	std::pair<Iterator, bool> nextParam(std::string& name, std::string& value,
796	                                    Iterator first, Iterator last, char delim)
797	{
798	  Iterator end = last;
799	  while (first != end) {
800	    last = first;
801	    Iterator parmnameFirst = first;
802	    Iterator parmnameLast = first;
803	    bool eqFound = false;
804	    for (; last != end; ++last) {
805	      if (*last == delim) {
806	        break;
807	      }
808	      else if (!eqFound && *last == '=') {
809	        eqFound = true;
810	        parmnameFirst = first;
811	        parmnameLast = last;
812	      }
813	    }
814	    std::pair<std::string::const_iterator, std::string::const_iterator> namep =
815	        std::make_pair(last, last);
816	    std::pair<std::string::const_iterator, std::string::const_iterator> valuep =
817	        std::make_pair(last, last);
818	    if (parmnameFirst == parmnameLast) {
819	      if (!eqFound) {
820	        parmnameFirst = first;
821	        parmnameLast = last;
822	        namep = stripIter(parmnameFirst, parmnameLast);
823	      }
824	    }
825	    else {
826	      first = parmnameLast + 1;
827	      namep = stripIter(parmnameFirst, parmnameLast);
828	      valuep = stripIter(first, last);
829	    }
830	    if (last != end) {
831	      ++last;
832	    }
833	    if (namep.first != namep.second) {
834	      name.assign(namep.first, namep.second);
835	      value.assign(valuep.first, valuep.second);
836	      return std::make_pair(last, true);
837	    }
838	    first = last;
839	  }
840	  return std::make_pair(end, false);
841	}
