314	bool File::utime(const Time& actime, const Time& modtime) const
315	{
316	#if defined(HAVE_UTIMES) && !defined(__MINGW32__)
317	  struct timeval times[2] = {{actime.getTimeFromEpoch(), 0},
318	                             {modtime.getTimeFromEpoch(), 0}};
319	  return utimes(name_.c_str(), times) == 0;
320	#elif defined(__MINGW32__)
321	  auto hn = openFile(name_, false);
322	  if (hn == INVALID_HANDLE_VALUE) {
323	    auto errNum = GetLastError();
324	    A2_LOG_ERROR(fmt(EX_FILE_OPEN, name_.c_str(),
325	                     util::formatLastError(errNum).c_str()));
326	    return false;
327	  }
328	  // Use SetFileTime because Windows _wutime takes DST into
329	  // consideration.
330	  //
331	  // std::chrono::time_point::time_since_epoch returns the amount of
332	  // time between it and epoch Jan 1, 1970.  OTOH, FILETIME structure
333	  // expects the epoch as Jan 1, 1601.  The resolution is 100
334	  // nanoseconds.
335	  constexpr auto offset = 116444736000000000LL;
336	  uint64_t at = std::chrono::duration_cast<std::chrono::nanoseconds>(
337	                    actime.getTime().time_since_epoch())
338	                        .count() /
339	                    100 +
340	                offset;
341	  uint64_t mt = std::chrono::duration_cast<std::chrono::nanoseconds>(
342	                    modtime.getTime().time_since_epoch())
343	                        .count() /
344	                    100 +
345	                offset;
346	  FILETIME att{static_cast<DWORD>(at & 0xffffffff),
347	               static_cast<DWORD>(at >> 32)};
348	  FILETIME mtt{static_cast<DWORD>(mt & 0xffffffff),
349	               static_cast<DWORD>(mt >> 32)};
350	  auto rv = SetFileTime(hn, nullptr, &att, &mtt);
351	  if (!rv) {
352	    auto errNum = GetLastError();
353	    A2_LOG_ERROR(fmt("SetFileTime failed, cause: %s",
354	                     util::formatLastError(errNum).c_str()));
355	  }
356	  CloseHandle(hn);
357	  return rv;
358	#else  // !defined(HAVE_UTIMES) && !defined(__MINGW32__)
359	  a2utimbuf ub;
360	  ub.actime = actime.getTimeFromEpoch();
361	  ub.modtime = modtime.getTimeFromEpoch();
362	  return a2utime(utf8ToWChar(name_).c_str(), &ub) == 0;
363	#endif // !defined(HAVE_UTIMES) && !defined(__MINGW32__)
364	}
