60	    uint64_t buf = 0;
61	    size_t bits = 0;
62	    for (size_t i = 0; i < 8; ++i) {
63	      char ch = *(first + i);
64	      unsigned char value;
65	      if ('A' <= ch && ch <= 'Z') {
66	        value = ch - 'A';
67	      }
68	      else if ('a' <= ch && ch <= 'z') {
69	        value = ch - 'a';
70	      }
71	      else if ('2' <= ch && ch <= '7') {
72	        value = ch - '2' + 26;
73	      }
